func (q *Queries) Submission(ctx context.Context, arg SubmissionParams) (HarvestSubmission, error) {
	row := q.db.QueryRow(ctx, submission, arg.Principal, arg.Key)
	var i HarvestSubmission
	err := row.Scan(
		&i.Principal,
		&i.Key,
		&i.RequestHash,
		&i.JobID,
	)
	return i, err
}
